import { createStyleContext } from "@utils/createStyleContext"
import { ChevronDown } from "lucide-react"
import { Accordion as AccordionPrimitive } from "radix-ui"
import { type ComponentPropsWithoutRef, ElementRef, forwardRef } from "react"

import { recipe } from "./recipe"

const { withContext, withProvider } = createStyleContext(recipe)

export const Root = withProvider(AccordionPrimitive.Root, "root")

export const Item = withContext(AccordionPrimitive.Item, "item")

export const Header = withContext(AccordionPrimitive.Header, "header")

const ContentWrapper = withContext("div", "contentWrapper")

const ContentPrimitive = forwardRef<
  ElementRef<typeof AccordionPrimitive.Content>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ children, ...props }, ref) => {
  return (
    <AccordionPrimitive.Content ref={ref} {...props}>
      <ContentWrapper>{children}</ContentWrapper>
    </AccordionPrimitive.Content>
  )
})

export const Content = withContext(ContentPrimitive, "content")

const TriggerPrimitive = forwardRef<
  ElementRef<typeof AccordionPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ children, ...props }, ref) => {
  return (
    <Header>
      <AccordionPrimitive.Trigger ref={ref} {...props}>
        {children}
        <ChevronDown />
      </AccordionPrimitive.Trigger>
    </Header>
  )
})

export const Trigger = withContext(TriggerPrimitive, "trigger")

import { tv, type VariantProps } from "tailwind-variants"

export const recipe = tv({
  slots: {
    root: "",
    item: "",
    header: "flex",
    trigger: [
      "flex flex-1 cursor-pointer items-center justify-between",
      "px-1 py-2 text-base/normal font-semibold text-base-content",
      "transition-colors",
      `
        [&>svg]:size-4 [&>svg]:shrink-0 [&>svg]:transition-transform
        [&>svg]:duration-200
      `,
      "data-[state=open]:[&>svg]:rotate-180",
    ],
    content: [
      "overflow-hidden text-sm/normal text-base-content/60",
      "transition-all",
      "data-[state=closed]:animate-accordion-up",
      "data-[state=open]:animate-accordion-down",
    ],
    contentWrapper: "px-1 py-1",
  },
  variants: {
    variant: {
      outline: {
        trigger: "hover:text-primary",
        item: "border-b border-base-300",
      },
      subtle: {
        item: `
          rounded-md
          data-[state=open]:bg-neutral
        `,
        header: "rounded-md",
        trigger: `
          rounded-md
          hover:rounded-md hover:bg-neutral
        `,
      },
    },
  },
  defaultVariants: {
    variant: "outline",
  },
})

export type AccordionVariants = VariantProps<typeof recipe>
